typedef struct {
    int id;
    void* resource_a;
    void* resource_b;
} Complex_T;

int Complex_init(Complex_T* obj, size_t size) {
    obj->resource_a = malloc(size);
    if (obj->resource_a == NULL) return -1;

    obj->resource_b = malloc(size / 2);
    if (obj->resource_b == NULL) {
        free(obj->resource_a); // Rollback upon failure
        return -1;
    }
    obj->id = 1;
    return 0;
}

void Complex_destroy(Complex_T* obj) {
    if (obj->resource_a) free(obj->resource_a);
    if (obj->resource_b) free(obj->resource_b);
}
